-- AgriReach PostgreSQL schema (Supabase-compatible), converted from the live MariaDB 10.4 schema.
--
-- Run once against an EMPTY Supabase database with:
--   php scripts/pgsql-migrate.php
-- Do not paste the MySQL dump into the Supabase SQL Editor; this file is the deliberate conversion.
--
-- Conversion rules applied (see docs/postgresql-migration.md for the full reasoning):
--   * AUTO_INCREMENT            -> GENERATED BY DEFAULT AS IDENTITY (explicit IDs can be imported;
--                                  sequences are reset afterwards by the transfer script).
--   * INT UNSIGNED / BIGINT UNSIGNED ids -> integer / bigint. SMALLINT UNSIGNED -> integer >= 0.
--   * TINYINT(1) flags          -> smallint CHECK (0/1). Kept numeric so PHP still receives 0/1 ints
--                                  and existing "= 1" / "= 0" SQL keeps working.
--   * ENUM(...)                 -> varchar + named CHECK constraint with the same value list.
--   * DATETIME / TIMESTAMP      -> timestamp(0) without time zone. Values keep the exact wall-clock
--                                  strings the PHP app read from MySQL (session time_zone +08:00).
--                                  *_utc columns and farmer_sessions times stay UTC, as before.
--   * DEFAULT current_timestamp -> agrireach_local_now() (Philippine wall clock, whole seconds),
--                                  independent of the connecting session's TimeZone.
--   * ON UPDATE current_timestamp -> BEFORE UPDATE trigger agrireach_touch_updated_at().
--   * utf8mb4_general_ci case-insensitive login/email columns -> citext.
--   * CHAR(n) ascii codes       -> varchar(n) (no blank padding on read).

BEGIN;

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS citext WITH SCHEMA extensions;

CREATE OR REPLACE FUNCTION public.agrireach_local_now()
RETURNS timestamp(0) without time zone
LANGUAGE sql
STABLE
SET search_path = ''
AS $$
    SELECT pg_catalog.date_trunc('second', pg_catalog.statement_timestamp() AT TIME ZONE 'Asia/Manila')::timestamp(0) without time zone
$$;

-- Mirrors MySQL "ON UPDATE current_timestamp()": refresh updated_at only when the row really
-- changed and the UPDATE did not assign updated_at itself.
CREATE OR REPLACE FUNCTION public.agrireach_touch_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
    IF NEW IS DISTINCT FROM OLD AND NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at THEN
        NEW.updated_at := public.agrireach_local_now();
    END IF;
    RETURN NEW;
END;
$$;

CREATE TABLE public.admins (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name varchar(120) NOT NULL,
    username extensions.citext NOT NULL,
    password_hash varchar(255) NOT NULL,
    role varchar(5) NOT NULL DEFAULT 'admin',
    status varchar(8) NOT NULL DEFAULT 'active',
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    contact_number varchar(40),
    email extensions.citext,
    address varchar(255),
    account_status varchar(8) NOT NULL DEFAULT 'Active',
    CONSTRAINT uq_admins_username UNIQUE (username),
    CONSTRAINT chk_admins_username_length CHECK (char_length(username) <= 60),
    CONSTRAINT chk_admins_email_length CHECK (char_length(email) <= 160),
    CONSTRAINT chk_admins_role CHECK (role IN ('admin')),
    CONSTRAINT chk_admins_status CHECK (status IN ('active', 'inactive')),
    CONSTRAINT chk_admins_account_status CHECK (account_status IN ('Active', 'Inactive', 'Blocked'))
);

CREATE TABLE public.farmers (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name varchar(150) NOT NULL,
    contact_number varchar(40) NOT NULL,
    email extensions.citext NOT NULL,
    address varchar(255) NOT NULL,
    residential_city_psgc_code varchar(10),
    residential_city_name varchar(100),
    residential_province_name varchar(100),
    residential_barangay_psgc_code varchar(10),
    residential_barangay_name varchar(100),
    residential_purok_sitio varchar(100),
    residential_landmark varchar(255),
    residential_location_method varchar(6) NOT NULL DEFAULT 'Legacy',
    residential_boundary_status varchar(23) NOT NULL DEFAULT 'Not Checked',
    residential_boundary_source varchar(255),
    residential_boundary_checked_at timestamp(0) without time zone,
    residential_latitude numeric(10,7),
    residential_longitude numeric(10,7),
    verification_status varchar(8) NOT NULL DEFAULT 'Pending',
    rejection_reason varchar(1000),
    date_registered timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    verified_at timestamp(0) without time zone,
    password_hash varchar(255),
    account_status varchar(8) NOT NULL DEFAULT 'Active',
    first_name varchar(75),
    last_name varchar(75),
    gender varchar(30),
    date_of_birth date,
    CONSTRAINT uq_farmers_email UNIQUE (email),
    CONSTRAINT uq_farmers_contact_number UNIQUE (contact_number),
    CONSTRAINT chk_farmers_email_length CHECK (char_length(email) <= 160),
    CONSTRAINT chk_farmers_residential_location_method CHECK (residential_location_method IN ('Legacy', 'Manual', 'Map')),
    CONSTRAINT chk_farmers_residential_boundary_status CHECK (residential_boundary_status IN ('Not Checked', 'Inside Mapped Boundary', 'Outside Mapped Boundary', 'Check Unavailable')),
    CONSTRAINT chk_farmers_verification_status CHECK (verification_status IN ('Pending', 'Approved', 'Rejected')),
    CONSTRAINT chk_farmers_account_status CHECK (account_status IN ('Active', 'Inactive', 'Blocked'))
);
CREATE INDEX idx_farmers_verification_status ON public.farmers (verification_status);
CREATE INDEX idx_farmers_residential_location ON public.farmers (residential_city_psgc_code, residential_barangay_psgc_code);
-- MySQL also had idx_farmers_email, an exact duplicate of uq_farmers_email; it is intentionally not recreated.

CREATE TABLE public.cabadbaran_barangays (
    psgc_code varchar(10) PRIMARY KEY,
    barangay_name varchar(100) NOT NULL,
    city_psgc_code varchar(10) NOT NULL DEFAULT '1600203000',
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT uq_cabadbaran_barangays_name UNIQUE (barangay_name)
);

CREATE TABLE public.farm_profiles (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    farmer_id integer NOT NULL,
    farm_name varchar(150) NOT NULL,
    farm_type varchar(100) NOT NULL,
    agricultural_category varchar(100) NOT NULL,
    land_area numeric(12,2),
    farm_address varchar(255) NOT NULL,
    city_psgc_code varchar(10),
    city_name varchar(100),
    province_name varchar(100),
    barangay_psgc_code varchar(10),
    barangay_name varchar(100),
    purok_sitio varchar(100),
    landmark varchar(255),
    location_method varchar(6) NOT NULL DEFAULT 'Legacy',
    location_boundary_status varchar(23) NOT NULL DEFAULT 'Not Checked',
    location_boundary_source varchar(255),
    location_boundary_checked_at timestamp(0) without time zone,
    location_review_status varchar(16) NOT NULL DEFAULT 'Needs Review',
    latitude numeric(10,7),
    longitude numeric(10,7),
    status varchar(8) NOT NULL DEFAULT 'Active',
    is_primary smallint NOT NULL DEFAULT 0,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    main_product varchar(150),
    CONSTRAINT fk_farm_profiles_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_farm_profiles_location_method CHECK (location_method IN ('Legacy', 'Manual', 'Map')),
    CONSTRAINT chk_farm_profiles_location_boundary_status CHECK (location_boundary_status IN ('Not Checked', 'Inside Mapped Boundary', 'Outside Mapped Boundary', 'Check Unavailable')),
    CONSTRAINT chk_farm_profiles_location_review_status CHECK (location_review_status IN ('Needs Review', 'Verified', 'Outside Coverage')),
    CONSTRAINT chk_farm_profiles_status CHECK (status IN ('Active', 'Archived')),
    CONSTRAINT chk_farm_profiles_is_primary CHECK (is_primary IN (0, 1))
);
CREATE INDEX idx_farm_profiles_advisory_location ON public.farm_profiles (location_review_status, city_psgc_code, barangay_psgc_code, agricultural_category);
CREATE INDEX idx_farm_profiles_farmer_status ON public.farm_profiles (farmer_id, status, is_primary);
CREATE TRIGGER trg_farm_profiles_updated_at BEFORE UPDATE ON public.farm_profiles FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.farmer_ids (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    farmer_id integer NOT NULL,
    id_type varchar(100) NOT NULL,
    id_number varchar(100),
    image_path varchar(255),
    front_image_path varchar(255),
    back_image_path varchar(255),
    uploaded_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT uq_farmer_ids_farmer UNIQUE (farmer_id),
    CONSTRAINT fk_farmer_ids_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE public.farmer_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    farmer_id integer NOT NULL,
    token_hash varchar(64) NOT NULL,
    expires_at timestamp(0) without time zone NOT NULL,
    revoked_at timestamp(0) without time zone,
    last_used_at timestamp(0) without time zone,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT uq_farmer_sessions_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_farmer_sessions_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE INDEX idx_farmer_sessions_farmer ON public.farmer_sessions (farmer_id);
CREATE INDEX idx_farmer_sessions_expiry ON public.farmer_sessions (expires_at, revoked_at);

CREATE TABLE public.damage_reports (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_code varchar(40) NOT NULL,
    farmer_id integer NOT NULL,
    farm_profile_id integer,
    agricultural_category varchar(100) NOT NULL,
    damage_type varchar(100) NOT NULL,
    damage_description text NOT NULL,
    estimated_damage_cost numeric(15,2) NOT NULL DEFAULT 0.00,
    final_assessed_cost numeric(15,2),
    assessment_remarks text,
    assessed_by_admin_id integer,
    assessed_at timestamp(0) without time zone,
    resolved_at timestamp(0) without time zone,
    status varchar(12) NOT NULL DEFAULT 'Received',
    submitted_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    submitted_address varchar(255),
    submitted_latitude numeric(10,7),
    submitted_longitude numeric(10,7),
    client_submission_id varchar(64),
    is_fixture smallint NOT NULL DEFAULT 0,
    distance_from_registered_farm numeric(10,3),
    gps_validation_status varchar(50),
    gps_validation_result varchar(255),
    image_metadata_validation_status varchar(50),
    timestamp_validation_status varchar(50),
    validation_warning varchar(1000),
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    location_source varchar(24),
    location_photo_order integer,
    location_confirmed_at timestamp(0) without time zone,
    CONSTRAINT uq_damage_reports_report_code UNIQUE (report_code),
    -- Same semantics as MySQL: NULL client_submission_id values never conflict with each other.
    CONSTRAINT uq_damage_reports_farmer_submission UNIQUE (farmer_id, client_submission_id),
    CONSTRAINT fk_damage_reports_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_damage_reports_farm_profile FOREIGN KEY (farm_profile_id) REFERENCES public.farm_profiles (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_damage_reports_status CHECK (status IN ('Received', 'Under Review', 'Approved', 'Rejected', 'Resolved')),
    CONSTRAINT chk_damage_reports_is_fixture CHECK (is_fixture IN (0, 1)),
    CONSTRAINT chk_damage_reports_location_photo_order CHECK (location_photo_order BETWEEN 0 AND 65535)
);
CREATE INDEX idx_damage_reports_status ON public.damage_reports (status);
CREATE INDEX idx_damage_reports_category ON public.damage_reports (agricultural_category);
CREATE INDEX idx_damage_reports_submitted_at ON public.damage_reports (submitted_at);
CREATE INDEX fk_damage_reports_farm_profile ON public.damage_reports (farm_profile_id);
CREATE TRIGGER trg_damage_reports_updated_at BEFORE UPDATE ON public.damage_reports FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();
-- Note: MySQL had no FK on assessed_by_admin_id; none is added here, to keep delete behavior identical.

CREATE TABLE public.admin_responses (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id integer NOT NULL,
    admin_id integer NOT NULL,
    previous_status varchar(50) NOT NULL,
    new_status varchar(50) NOT NULL,
    response_message text,
    rejection_reason varchar(1000),
    notification_message text,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_admin_responses_report FOREIGN KEY (report_id) REFERENCES public.damage_reports (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_admin_responses_admin FOREIGN KEY (admin_id) REFERENCES public.admins (id) ON UPDATE CASCADE
);
CREATE INDEX idx_admin_responses_report ON public.admin_responses (report_id);
CREATE INDEX fk_admin_responses_admin ON public.admin_responses (admin_id);

CREATE TABLE public.admin_settings (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    admin_id integer NOT NULL,
    new_farmer_registration smallint NOT NULL DEFAULT 1,
    farmer_verification_updates smallint NOT NULL DEFAULT 1,
    new_damage_reports smallint NOT NULL DEFAULT 1,
    damage_report_status_changes smallint NOT NULL DEFAULT 1,
    weather_advisory_updates smallint NOT NULL DEFAULT 1,
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT uq_admin_settings_admin UNIQUE (admin_id),
    CONSTRAINT fk_admin_settings_admin FOREIGN KEY (admin_id) REFERENCES public.admins (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_admin_settings_flags CHECK (
        new_farmer_registration IN (0, 1) AND farmer_verification_updates IN (0, 1) AND new_damage_reports IN (0, 1)
        AND damage_report_status_changes IN (0, 1) AND weather_advisory_updates IN (0, 1)
    )
);
CREATE TRIGGER trg_admin_settings_updated_at BEFORE UPDATE ON public.admin_settings FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.damage_report_assessment_audit (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id integer NOT NULL,
    admin_id integer NOT NULL,
    action varchar(8) NOT NULL,
    old_assessed_cost numeric(15,2),
    new_assessed_cost numeric(15,2),
    old_remarks text,
    new_remarks text,
    previous_status varchar(50) NOT NULL,
    new_status varchar(50) NOT NULL,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_damage_assessment_report FOREIGN KEY (report_id) REFERENCES public.damage_reports (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_damage_assessment_admin FOREIGN KEY (admin_id) REFERENCES public.admins (id) ON UPDATE CASCADE,
    CONSTRAINT chk_damage_assessment_action CHECK (action IN ('Saved', 'Resolved'))
);
CREATE INDEX idx_damage_assessment_report ON public.damage_report_assessment_audit (report_id, id);
CREATE INDEX fk_damage_assessment_admin ON public.damage_report_assessment_audit (admin_id);

CREATE TABLE public.report_images (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id integer NOT NULL,
    image_path varchar(255) NOT NULL,
    display_order integer NOT NULL DEFAULT 0,
    captured_at timestamp(0) without time zone,
    gps_latitude numeric(10,7),
    gps_longitude numeric(10,7),
    metadata_validation_status varchar(50),
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    gps_source varchar(24),
    gps_accuracy_m numeric(10,2),
    gps_recorded_at timestamp(0) without time zone,
    capture_time_source varchar(24),
    location_status varchar(32),
    CONSTRAINT fk_report_images_report FOREIGN KEY (report_id) REFERENCES public.damage_reports (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_report_images_display_order CHECK (display_order BETWEEN 0 AND 65535)
);
CREATE INDEX idx_report_images_report ON public.report_images (report_id);

CREATE TABLE public.weather_advisories (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title varchar(180) NOT NULL,
    agricultural_category varchar(100) NOT NULL,
    weather_condition varchar(100) NOT NULL,
    location_coverage varchar(255) NOT NULL,
    coverage_scope varchar(9) NOT NULL DEFAULT 'City',
    coverage_city_psgc_code varchar(10) NOT NULL DEFAULT '1600203000',
    coverage_city_name varchar(100) NOT NULL DEFAULT 'Cabadbaran City',
    coverage_province_name varchar(100) NOT NULL DEFAULT 'Agusan del Norte',
    advisory_message text NOT NULL,
    effective_date date NOT NULL,
    expiration_date date,
    status varchar(8) NOT NULL DEFAULT 'Draft',
    published_at timestamp(0) without time zone,
    created_by integer NOT NULL,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_weather_advisories_admin FOREIGN KEY (created_by) REFERENCES public.admins (id) ON UPDATE CASCADE,
    CONSTRAINT chk_weather_advisories_coverage_scope CHECK (coverage_scope IN ('City', 'Barangays')),
    CONSTRAINT chk_weather_advisories_status CHECK (status IN ('Draft', 'Active', 'Archived'))
);
CREATE INDEX idx_weather_advisories_category ON public.weather_advisories (agricultural_category);
CREATE INDEX idx_weather_advisories_status_dates ON public.weather_advisories (status, effective_date, expiration_date);
CREATE INDEX fk_weather_advisories_admin ON public.weather_advisories (created_by);
CREATE TRIGGER trg_weather_advisories_updated_at BEFORE UPDATE ON public.weather_advisories FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.notifications (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    farmer_id integer NOT NULL,
    notification_type varchar(100) NOT NULL,
    title varchar(180) NOT NULL,
    message text NOT NULL,
    related_report_id integer,
    related_advisory_id integer,
    is_read smallint NOT NULL DEFAULT 0,
    created_by integer,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_notifications_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_notifications_report FOREIGN KEY (related_report_id) REFERENCES public.damage_reports (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_notifications_advisory FOREIGN KEY (related_advisory_id) REFERENCES public.weather_advisories (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_notifications_admin FOREIGN KEY (created_by) REFERENCES public.admins (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_notifications_is_read CHECK (is_read IN (0, 1))
);
CREATE INDEX idx_notifications_farmer_read ON public.notifications (farmer_id, is_read);
CREATE INDEX idx_notifications_type_date ON public.notifications (notification_type, created_at);
CREATE INDEX fk_notifications_report ON public.notifications (related_report_id);
CREATE INDEX fk_notifications_advisory ON public.notifications (related_advisory_id);
CREATE INDEX fk_notifications_admin ON public.notifications (created_by);

CREATE TABLE public.admin_notification_state (
    admin_id integer NOT NULL,
    notification_id integer NOT NULL,
    is_read smallint NOT NULL DEFAULT 0,
    is_archived smallint NOT NULL DEFAULT 0,
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    PRIMARY KEY (admin_id, notification_id),
    CONSTRAINT fk_admin_notice_admin FOREIGN KEY (admin_id) REFERENCES public.admins (id) ON DELETE CASCADE,
    CONSTRAINT fk_admin_notice_record FOREIGN KEY (notification_id) REFERENCES public.notifications (id) ON DELETE CASCADE,
    CONSTRAINT chk_admin_notice_flags CHECK (is_read IN (0, 1) AND is_archived IN (0, 1))
);
CREATE INDEX fk_admin_notice_record ON public.admin_notification_state (notification_id);
CREATE TRIGGER trg_admin_notification_state_updated_at BEFORE UPDATE ON public.admin_notification_state FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.registration_email_settings (
    id smallint NOT NULL DEFAULT 1 PRIMARY KEY,
    sender_email varchar(160) NOT NULL,
    app_password_ciphertext text NOT NULL,
    app_password_iv varchar(64) NOT NULL,
    app_password_tag varchar(64) NOT NULL,
    last_test_status varchar(10) NOT NULL DEFAULT 'Not Tested',
    last_tested_at timestamp(0) without time zone,
    last_test_error_code varchar(80),
    configured_by integer,
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_registration_email_admin FOREIGN KEY (configured_by) REFERENCES public.admins (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_registration_email_singleton CHECK (id = 1),
    CONSTRAINT chk_registration_email_last_test_status CHECK (last_test_status IN ('Not Tested', 'Accepted', 'Failed'))
);
CREATE INDEX fk_registration_email_admin ON public.registration_email_settings (configured_by);
CREATE TRIGGER trg_registration_email_settings_updated_at BEFORE UPDATE ON public.registration_email_settings FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.registration_email_templates (
    decision varchar(8) NOT NULL PRIMARY KEY,
    subject varchar(180) NOT NULL,
    message_body text NOT NULL,
    updated_by integer,
    updated_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT fk_registration_email_template_admin FOREIGN KEY (updated_by) REFERENCES public.admins (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_registration_email_template_decision CHECK (decision IN ('Approved', 'Rejected'))
);
CREATE INDEX fk_registration_email_template_admin ON public.registration_email_templates (updated_by);
CREATE TRIGGER trg_registration_email_templates_updated_at BEFORE UPDATE ON public.registration_email_templates FOR EACH ROW EXECUTE FUNCTION public.agrireach_touch_updated_at();

CREATE TABLE public.verification_email_deliveries (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    farmer_id integer NOT NULL,
    admin_id integer,
    decision varchar(8) NOT NULL,
    recipient_email varchar(160) NOT NULL,
    delivery_recipient_email varchar(160),
    routing_mode varchar(16) NOT NULL DEFAULT 'Unknown',
    transport varchar(20) NOT NULL,
    status varchar(9) NOT NULL DEFAULT 'Pending',
    failure_code varchar(80),
    retry_of_delivery_id bigint,
    attempted_at timestamp(0) without time zone,
    delivered_at timestamp(0) without time zone,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    -- One retry per failed delivery (duplicate-retry prevention relies on this unique key).
    CONSTRAINT uq_verification_email_retry UNIQUE (retry_of_delivery_id),
    CONSTRAINT fk_verification_email_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_verification_email_admin FOREIGN KEY (admin_id) REFERENCES public.admins (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_verification_email_retry FOREIGN KEY (retry_of_delivery_id) REFERENCES public.verification_email_deliveries (id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_verification_email_decision CHECK (decision IN ('Approved', 'Rejected')),
    CONSTRAINT chk_verification_email_routing_mode CHECK (routing_mode IN ('Live', 'Development Test', 'Unknown')),
    CONSTRAINT chk_verification_email_status CHECK (status IN ('Pending', 'Sent', 'Failed', 'Simulated'))
);
CREATE INDEX idx_verification_email_farmer ON public.verification_email_deliveries (farmer_id, decision, created_at);
CREATE INDEX idx_verification_email_status ON public.verification_email_deliveries (status, created_at);
CREATE INDEX fk_verification_email_admin ON public.verification_email_deliveries (admin_id);

CREATE TABLE public.weather_advisory_barangays (
    advisory_id integer NOT NULL,
    barangay_code varchar(10) NOT NULL,
    barangay_name varchar(100) NOT NULL,
    PRIMARY KEY (advisory_id, barangay_code),
    CONSTRAINT fk_weather_advisory_barangays_advisory FOREIGN KEY (advisory_id) REFERENCES public.weather_advisories (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_weather_advisory_barangays_barangay FOREIGN KEY (barangay_code) REFERENCES public.cabadbaran_barangays (psgc_code) ON UPDATE CASCADE
);
CREATE INDEX fk_weather_advisory_barangays_barangay ON public.weather_advisory_barangays (barangay_code);

CREATE TABLE public.weather_advisory_recipients (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    advisory_id integer NOT NULL,
    farmer_id integer NOT NULL,
    notification_id integer,
    notified_at timestamp(0) without time zone,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    CONSTRAINT uq_weather_advisory_farmer UNIQUE (advisory_id, farmer_id),
    CONSTRAINT fk_weather_advisory_recipients_advisory FOREIGN KEY (advisory_id) REFERENCES public.weather_advisories (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_weather_advisory_recipients_farmer FOREIGN KEY (farmer_id) REFERENCES public.farmers (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_weather_advisory_recipients_notification FOREIGN KEY (notification_id) REFERENCES public.notifications (id) ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX idx_weather_advisory_recipients_farmer ON public.weather_advisory_recipients (farmer_id, advisory_id);
CREATE INDEX fk_weather_advisory_recipients_notification ON public.weather_advisory_recipients (notification_id);

CREATE TABLE public.weather_data (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    report_id integer NOT NULL,
    snapshot_status varchar(11) NOT NULL DEFAULT 'Available',
    unavailable_reason varchar(255),
    unavailable_code varchar(40),
    weather_condition varchar(100),
    temperature numeric(6,2),
    humidity numeric(6,2),
    rainfall numeric(10,2),
    wind_information varchar(255),
    recorded_at timestamp(0) without time zone,
    created_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now(),
    provider varchar(60),
    observation_type varchar(80),
    requested_latitude numeric(10,7),
    requested_longitude numeric(10,7),
    provider_latitude numeric(10,6),
    provider_longitude numeric(10,6),
    location_basis varchar(24),
    observed_at_utc timestamp(0) without time zone,
    retrieved_at_utc timestamp(0) without time zone,
    report_submitted_at_utc timestamp(0) without time zone,
    weather_code smallint,
    apparent_temperature numeric(6,2),
    precipitation_mm numeric(8,2),
    precipitation_last_6h_mm numeric(8,2),
    wind_speed_kmh numeric(6,2),
    wind_gust_kmh numeric(6,2),
    wind_direction_deg smallint,
    units_json varchar(500),
    rule_set_version varchar(30),
    rule_category varchar(100),
    rule_result_json text,
    CONSTRAINT uq_weather_data_report UNIQUE (report_id),
    CONSTRAINT fk_weather_data_report FOREIGN KEY (report_id) REFERENCES public.damage_reports (id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_weather_data_snapshot_status CHECK (snapshot_status IN ('Available', 'Unavailable'))
);
-- MySQL also had idx_weather_data_report, an exact duplicate of uq_weather_data_report; not recreated.

CREATE TABLE public.agrireach_schema_migrations (
    version varchar(64) PRIMARY KEY,
    applied_at timestamp(0) without time zone NOT NULL DEFAULT public.agrireach_local_now()
);

-- Supabase exposes the public schema through its Data API. AgriReach never uses that API (PHP talks
-- to Postgres directly), so lock it out: RLS on with no policies, and no grants for API roles.
DO $$
DECLARE
    table_name text;
BEGIN
    FOR table_name IN
        SELECT c.relname FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND c.relkind = 'r'
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
    END LOOP;

    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN
        REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon;
        REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon;
        REVOKE EXECUTE ON FUNCTION public.agrireach_local_now(), public.agrireach_touch_updated_at() FROM anon;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN
        REVOKE ALL ON ALL TABLES IN SCHEMA public FROM authenticated;
        REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM authenticated;
        REVOKE EXECUTE ON FUNCTION public.agrireach_local_now(), public.agrireach_touch_updated_at() FROM authenticated;
    END IF;
END;
$$;

INSERT INTO public.agrireach_schema_migrations (version) VALUES ('20261016_0001_agrireach_schema');

COMMIT;
